const errorTitles: Partial<Record<ConnectionState, string>> = {
  'no-transport': 'The Agent panel has no connection to JusPrin',
  timeout: 'The Agent panel could not reach JusPrin',
  incompatible: 'This Agent panel does not match this JusPrin build',
};

export function App({
  getTransport,
  handshakeTimeoutMs,
  transportRetryMs,
  transportRetryLimit,
  draftDebounceMs,
  embedded,
  printerPanel,
}: AppProps) {
  const [state, dispatch] = useReducer(reducer, initialState);
  const stateRef = useRef<AgentUiState>(state);
  stateRef.current = state;

  // Which setup screen the dock is showing. This is page-local on purpose:
  // the host cares which credentials it was asked to check, not which panel
  // is on screen, so navigating setup costs no bridge traffic.
  const [setupScreen, setSetupScreen] = useState<'offer' | 'chooser' | 'apiKey' | 'localTool'>('offer');
  const [view, setView] = useState<'chat' | 'list' | 'setup'>('chat');
  // The setup card's expansion is a temporary layer over the thread, so it is
  // page-local and closes on its own the moment the user does something else.
  const [setupExpanded, setSetupExpanded] = useState(false);
              draftDebounceMs={0}
              onSend={(text) => { printerDraft.current = ''; sendMessage(text); }}
              onStop={() => {
                if (state.streamingMessageId) client.send('stop_generation', { messageId: state.streamingMessageId });
              }}
              onAttachFiles={attachFiles}
              onRemoveAttachment={removeAttachment}
            />
          )}
        </div>
      </div>
    );
  }

  if (embedded) {
    // No conversation header, chat list, composer, or external-tool banner --
    // just the setup sub-component itself, at whatever size its host gives it.
    return (
      <div className="app app--embedded">
        {errorNotice}
        <div className="chat-content">{body()}</div>
      </div>
    );
  }

  return (
    <div className={state.navigation.focused ? 'app app--focused-chat' : 'app'}>
      {errorNotice}
      {externalActions.length > 0 && <section className="external-actions" aria-label="External AI tools">
        <h2>External AI tools</h2>
        {externalActions.map((activity) => {
          const key = planKey(activity);
          const found = key ? externalPlans.get(key) : undefined;
          // A plan of one change is decided like any other call.
          const members = found && found.length > 1 ? found : undefined;
          if (members && members[0].actionId !== activity.actionId) return null;
          return members
            ? <PlanActivityCard key={activity.actionId} members={members} headline={planHeadline(state.toolActivities)}
                onDecision={sendToolDecision} onCancel={sendToolCancel} />
            : <ToolActivityCard key={activity.actionId} activity={activity}
                onDecision={sendToolDecision} onCancel={sendToolCancel} />;
        })}
      </section>}
      {view === 'list' && !state.navigation.focused && chatList}
      <div className="chat-content" hidden={view === 'list'}>
      {notConfigured && state.conversations.length === 1 && view !== 'setup' && !state.navigation.focused ? (
        <>
          <AgentNotConfiguredHeader onCollapse={collapseAgentPane} />
          {setupCard}
        </>
      ) : state.navigation.focused ? (
        <header className="chat-header printer-header">
          <button type="button" className="printer-link-button printer-back-link" aria-label={state.navigation.returnLabel ?? 'Back to Prepare'}
            onClick={() => { if (view === 'setup') closeSetup(); else returnToWorkspace(); }}><span className="jp-icon jp-icon-chevron-left" aria-hidden="true" /> Back</button>
          {view !== 'setup' && <button type="button" className="printer-link-button"
            onClick={() => client.send('shell_action', { action: 'open_filament_settings' })}>Open filament settings</button>}
          <AgentPaneToggle onCollapse={collapseAgentPane} />
        </header>
      ) : (
        <>
          <ChatHeader key={`header-${state.context?.sessionId}-${viewedId}`} title={viewedChat?.title || 'New chat'} busy={busy || pendingAction}
            onBack={() => { collapseSetup(); if (view === 'setup') closeSetup(); else { client.send('state_request', {}); setView('list'); } }}
            onCreate={createChat}
            onRename={(title) => client.send('rename_conversation', { conversationId: viewedId, title })}
            onDelete={() => { client.send('delete_conversation', { conversationId: viewedId }); setView('list'); }}
            onCollapse={collapseAgentPane} />
          {setupCard}
        </>
      )}
      {!notConfigured && connected && (
        <ConnectedBanner
          provider={connected.provider}
          warning={connected.warning}
          onDismiss={() => setConnected(null)}
        />
      )}
      {body()}
      {/* An earlier chat is read-only: its composer is an empty, disabled
          shell under the notice, with no draft and no attachments. */}
      {view === 'chat' && historical && <Composer
        key={`composer-historical-${viewedId}`}
        disabled
        disabledReason=""
        attachable={false}
        streaming={false}
        attachments={[]}
        notice={<>{blockedAlert}{projectUpdates}</>}
        onSend={() => {}}
        onStop={() => {}}
        onAttachFiles={() => {}}
        onRemoveAttachment={() => {}}
      ))}
    </div>
  );
});

// printer_connect's card. Connect approves the call and hands the app what
// was typed; the model hears only how the connection went. After Connect the
// card follows the attempt itself, as the app reports it in `connection`.
export function PrinterCredentialCard({
  activity,
  connection,
  model,
  onDecision,
  onCancelConnection,
}: {
  activity: ToolActivityInfo;
  connection?: PrinterConnectionInfo;
  // What kind of printer the conversation is about, when the app knows.
  model?: string;
  onDecision: (actionId: string, decision: 'approve' | 'reject', input?: { credential: string }) => void;
  onCancelConnection: (actionId: string) => void;
}) {
  const [credential, setCredential] = useState('');
  const bambu = activity.arguments.provider === 'bambu';
  if (activity.state !== 'pending') {
    // Approved and about to start, or started: both are the wait.
    const state =
      activity.state === 'rejected' ? 'cancelled' : connection?.state ?? (activity.state === 'failed' ? 'failed' : 'connecting');
    const target = connection?.target;
    // A figure only when the app has measured one, kept inside its range.
    const percent = typeof connection?.percent === 'number' && Number.isFinite(connection.percent)
      ? Math.round(Math.min(100, Math.max(0, connection.percent))) : undefined;
    return (
      <div className="tool-card printer-credential" data-testid={`tool-${activity.actionId}`}>
        <div className="tool-title">{activity.title}</div>
        {state === 'connecting' && (
          <>
            <ToolStatus state="running">{percent === undefined ? 'Connecting…' : `Connecting · ${percent}%`}</ToolStatus>
            <Progress label="Connecting" value={percent} max={percent === undefined ? undefined : 100} />
            {connection && <button type="button" className="printer-link-button printer-credential-cancel" onClick={() => onCancelConnection(activity.actionId)}>Cancel</button>}
          </>
        )}
        {state === 'verified' && <ToolStatus state="succeeded">{target ? `Connected to ${target}.` : 'Connected.'}</ToolStatus>}
        {state === 'failed' && <ToolStatus state="failed">{target ? `Couldn't reach ${target}` : "Couldn't connect"}</ToolStatus>}
        {state === 'cancelled' && <ToolStatus state="cancelled">Cancelled. No connection was made.</ToolStatus>}
      </div>
    );
  }
  return (
    <form
      className="tool-card printer-credential"
      data-testid={`tool-${activity.actionId}`}
      onSubmit={(event) => {
        event.preventDefault();
        onDecision(activity.actionId, 'approve', { credential });
      }}
    >
      <div className="printer-notice-heading">
        <PrinterGlyph className="printer-credential-glyph" />
        <span className="tool-title">{activity.title}</span>
      </div>
      <div className="printer-credential-state">{model ? `Pending · ${model}` : 'Pending'}</div>
      <label className="printer-credential-field">
        <span>{bambu ? 'Access code' : 'API key (if the printer asks for one)'}</span>
        <input
          type="password"
          className="printer-credential-input"
          autoComplete="off"
          value={credential}
          onChange={(event) => setCredential(event.target.value)}
        />
      </label>
      <p className="printer-credential-note">Stays on this computer.</p>
      <div className="tool-actions">
        {/* Enabled while empty: a printer that already has its code needs none. */}
        <button type="submit" className="primary">

